-- Latest single-file schema for the local learning game.
-- This migration is intentionally mutable; startup can rebuild the local schema
-- when the recorded database history no longer matches this file.

CREATE TABLE account (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(64) NOT NULL,
    password_hash VARCHAR(256) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uk_account_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE session_token (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    account_id BIGINT NOT NULL,
    token VARCHAR(96) NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_session_token (token),
    KEY idx_session_account (account_id),
    CONSTRAINT fk_session_account FOREIGN KEY (account_id) REFERENCES account (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE player (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    account_id BIGINT NULL,
    name VARCHAR(32) NOT NULL,
    profession VARCHAR(32) NOT NULL,
    level INT NOT NULL DEFAULT 1,
    experience INT NOT NULL DEFAULT 0,
    gold INT NOT NULL DEFAULT 100,
    strength INT NOT NULL,
    agility INT NOT NULL,
    constitution INT NOT NULL,
    intelligence INT NOT NULL,
    spirit INT NOT NULL,
    free_points INT NOT NULL DEFAULT 0,
    controller_type VARCHAR(16) NOT NULL DEFAULT 'player',
    title VARCHAR(64) NOT NULL DEFAULT '玩家',
    personality VARCHAR(64) NOT NULL DEFAULT '',
    dungeon_clears INT NOT NULL DEFAULT 0,
    peak_enhancement INT NOT NULL DEFAULT 0,
    legendary_loot_count INT NOT NULL DEFAULT 0,
    current_activity_kind VARCHAR(32) NOT NULL DEFAULT 'rest',
    current_activity_text VARCHAR(240) NOT NULL DEFAULT '正在公会大厅整理装备。',
    current_activity_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_activity_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uk_player_account (account_id),
    UNIQUE KEY uk_player_name (name),
    KEY idx_player_controller (controller_type, level, gold),
    CONSTRAINT fk_player_account FOREIGN KEY (account_id) REFERENCES account (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE item_template (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    item_type VARCHAR(32) NOT NULL,
    quality VARCHAR(32) NOT NULL,
    required_level INT NOT NULL,
    attack_bonus INT NOT NULL,
    defense_bonus INT NOT NULL,
    hp_bonus INT NOT NULL,
    mp_bonus INT NOT NULL,
    crit_bonus DECIMAL(10, 6) NOT NULL,
    random_range INT NOT NULL,
    description VARCHAR(1000) NOT NULL,
    sell_price INT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE monster_config (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    level INT NOT NULL,
    max_hp INT NOT NULL,
    strength INT NOT NULL,
    is_boss BOOLEAN NOT NULL,
    exp_reward INT NOT NULL,
    gold_reward INT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE monster_loot (
    monster_id VARCHAR(64) NOT NULL,
    item_id VARCHAR(64) NOT NULL,
    drop_rate DECIMAL(10, 6) NOT NULL,
    PRIMARY KEY (monster_id, item_id),
    CONSTRAINT fk_monster_loot_monster FOREIGN KEY (monster_id) REFERENCES monster_config (id),
    CONSTRAINT fk_monster_loot_item FOREIGN KEY (item_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_config (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    description VARCHAR(1000) NOT NULL,
    difficulty VARCHAR(32) NOT NULL,
    recommended_level INT NOT NULL,
    recommended_power INT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_room (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_id VARCHAR(64) NOT NULL,
    room_config_id VARCHAR(64) NOT NULL,
    room_order INT NOT NULL,
    is_boss_room BOOLEAN NOT NULL,
    UNIQUE KEY uk_dungeon_room_config (dungeon_id, room_config_id),
    KEY idx_dungeon_room_order (dungeon_id, room_order),
    CONSTRAINT fk_dungeon_room_dungeon FOREIGN KEY (dungeon_id) REFERENCES dungeon_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_room_monster (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    room_id BIGINT NOT NULL,
    monster_id VARCHAR(64) NOT NULL,
    monster_count INT NOT NULL,
    KEY idx_room_monster_room (room_id),
    CONSTRAINT fk_room_monster_room FOREIGN KEY (room_id) REFERENCES dungeon_room (id),
    CONSTRAINT fk_room_monster_monster FOREIGN KEY (monster_id) REFERENCES monster_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_config (
    id VARCHAR(96) PRIMARY KEY,
    title VARCHAR(128) NOT NULL,
    category VARCHAR(32) NOT NULL,
    description VARCHAR(500) NOT NULL,
    lore VARCHAR(1000) NULL,
    priority INT NOT NULL,
    navigation_target VARCHAR(64) NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_prerequisite (
    quest_id VARCHAR(96) NOT NULL,
    prerequisite_id VARCHAR(96) NOT NULL,
    PRIMARY KEY (quest_id, prerequisite_id),
    CONSTRAINT fk_quest_prereq_quest FOREIGN KEY (quest_id) REFERENCES quest_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_condition (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    quest_id VARCHAR(96) NOT NULL,
    condition_id VARCHAR(96) NOT NULL,
    condition_type VARCHAR(64) NOT NULL,
    target_id VARCHAR(96) NULL,
    target_value INT NOT NULL,
    condition_order INT NOT NULL,
    KEY idx_quest_condition_quest (quest_id),
    CONSTRAINT fk_quest_condition_quest FOREIGN KEY (quest_id) REFERENCES quest_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_reward (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    quest_id VARCHAR(96) NOT NULL,
    reward_type VARCHAR(64) NOT NULL,
    target_id VARCHAR(96) NULL,
    amount INT NOT NULL,
    reward_order INT NOT NULL,
    KEY idx_quest_reward_quest (quest_id),
    CONSTRAINT fk_quest_reward_quest FOREIGN KEY (quest_id) REFERENCES quest_config (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE item_instance (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    template_id VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    item_type VARCHAR(32) NOT NULL,
    quality VARCHAR(32) NOT NULL,
    required_level INT NOT NULL,
    attack_bonus INT NOT NULL,
    defense_bonus INT NOT NULL,
    hp_bonus INT NOT NULL,
    mp_bonus INT NOT NULL,
    crit_bonus DECIMAL(10, 6) NOT NULL,
    sell_price INT NOT NULL,
    enhancement_level INT NOT NULL DEFAULT 0,
    enhancement_luck INT NOT NULL DEFAULT 0,
    market_lock_until TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_item_player (player_id),
    KEY idx_item_template (template_id),
    CONSTRAINT fk_item_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE inventory_slot (
    player_id BIGINT NOT NULL,
    slot_index INT NOT NULL,
    item_id BIGINT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, slot_index),
    UNIQUE KEY uk_inventory_item (item_id),
    CONSTRAINT fk_inventory_player FOREIGN KEY (player_id) REFERENCES player (id),
    CONSTRAINT fk_inventory_item FOREIGN KEY (item_id) REFERENCES item_instance (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE equipment_slot (
    player_id BIGINT NOT NULL,
    slot_name VARCHAR(32) NOT NULL,
    item_id BIGINT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, slot_name),
    UNIQUE KEY uk_equipment_item (item_id),
    CONSTRAINT fk_equipment_player FOREIGN KEY (player_id) REFERENCES player (id),
    CONSTRAINT fk_equipment_item FOREIGN KEY (item_id) REFERENCES item_instance (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    dungeon_id VARCHAR(64) NOT NULL,
    config_version VARCHAR(64) NOT NULL,
    request_id VARCHAR(96) NULL,
    success BOOLEAN NOT NULL,
    rating VARCHAR(8) NOT NULL,
    monsters_killed INT NOT NULL,
    exp_gained INT NOT NULL,
    gold_gained INT NOT NULL,
    combat_power INT NOT NULL DEFAULT 0,
    recommended_power INT NOT NULL DEFAULT 0,
    player_max_hp INT NOT NULL DEFAULT 0,
    player_final_hp INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_dungeon_run_request (player_id, request_id),
    KEY idx_dungeon_run_player (player_id),
    CONSTRAINT fk_dungeon_run_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run_loot (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_run_id BIGINT NOT NULL,
    loot_order INT NOT NULL,
    item_id BIGINT NULL,
    item_template_id VARCHAR(64) NOT NULL,
    item_name VARCHAR(128) NOT NULL,
    item_type VARCHAR(32) NOT NULL,
    quality VARCHAR(32) NOT NULL,
    required_level INT NOT NULL,
    attack_bonus INT NOT NULL,
    defense_bonus INT NOT NULL,
    hp_bonus INT NOT NULL,
    mp_bonus INT NOT NULL,
    crit_bonus DECIMAL(10, 6) NOT NULL,
    sell_price INT NOT NULL,
    enhancement_level INT NOT NULL DEFAULT 0,
    enhancement_luck INT NOT NULL DEFAULT 0,
    KEY idx_run_loot_run (dungeon_run_id),
    KEY idx_run_loot_template (item_template_id),
    CONSTRAINT fk_run_loot_run FOREIGN KEY (dungeon_run_id) REFERENCES dungeon_run (id) ON DELETE CASCADE,
    CONSTRAINT fk_run_loot_template FOREIGN KEY (item_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run_log (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_run_id BIGINT NOT NULL,
    log_order INT NOT NULL,
    text VARCHAR(1000) NOT NULL,
    KEY idx_run_log_run (dungeon_run_id, log_order),
    CONSTRAINT fk_run_log_run FOREIGN KEY (dungeon_run_id) REFERENCES dungeon_run (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE dungeon_run_frame (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    dungeon_run_id BIGINT NOT NULL,
    frame_index INT NOT NULL,
    text VARCHAR(1000) NOT NULL,
    tone VARCHAR(32) NOT NULL,
    room_label VARCHAR(64) NULL,
    enemy_name VARCHAR(128) NULL,
    player_hp INT NOT NULL DEFAULT 0,
    player_max_hp INT NOT NULL DEFAULT 0,
    enemy_hp INT NOT NULL DEFAULT 0,
    enemy_max_hp INT NOT NULL DEFAULT 0,
    KEY idx_run_frame_run (dungeon_run_id, frame_index),
    CONSTRAINT fk_run_frame_run FOREIGN KEY (dungeon_run_id) REFERENCES dungeon_run (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE economy_audit_event (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    event_type VARCHAR(64) NOT NULL,
    reference_id VARCHAR(96) NULL,
    dungeon_id VARCHAR(64) NULL,
    success BOOLEAN NULL,
    rating VARCHAR(8) NULL,
    monsters_killed INT NOT NULL DEFAULT 0,
    exp_gained INT NOT NULL DEFAULT 0,
    gold_gained INT NOT NULL DEFAULT 0,
    loot_count INT NOT NULL DEFAULT 0,
    sweep_times INT NOT NULL DEFAULT 0,
    combat_power INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_economy_player (player_id),
    KEY idx_economy_dungeon (dungeon_id),
    CONSTRAINT fk_economy_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE config_bundle (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    version VARCHAR(64) NOT NULL,
    checksum VARCHAR(64) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_config_version (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE quest_progress (
    player_id BIGINT NOT NULL,
    quest_id VARCHAR(96) NOT NULL,
    status VARCHAR(24) NOT NULL,
    current_value INT NOT NULL DEFAULT 0,
    cycle_key VARCHAR(16) NULL,
    claimed_at TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (player_id, quest_id),
    CONSTRAINT fk_quest_progress_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE market_listing (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    seller_player_id BIGINT NULL,
    seller_name VARCHAR(64) NOT NULL,
    item_id BIGINT NULL,
    item_template_id VARCHAR(64) NOT NULL,
    item_enhancement_level INT NOT NULL DEFAULT 0,
    item_enhancement_luck INT NOT NULL DEFAULT 0,
    price INT NOT NULL,
    status VARCHAR(24) NOT NULL,
    buyer_player_id BIGINT NULL,
    sold_at TIMESTAMP NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_market_status (status, created_at),
    KEY idx_market_seller (seller_player_id),
    KEY idx_market_item_template (item_template_id),
    CONSTRAINT fk_market_seller FOREIGN KEY (seller_player_id) REFERENCES player (id),
    CONSTRAINT fk_market_buyer FOREIGN KEY (buyer_player_id) REFERENCES player (id),
    CONSTRAINT fk_market_item FOREIGN KEY (item_id) REFERENCES item_instance (id),
    CONSTRAINT fk_market_listing_template FOREIGN KEY (item_template_id) REFERENCES item_template (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE chat_message (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NULL,
    sender_name VARCHAR(64) NOT NULL,
    kind VARCHAR(32) NOT NULL,
    text VARCHAR(500) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_chat_created (created_at),
    CONSTRAINT fk_chat_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE global_announcement (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    kind VARCHAR(32) NOT NULL,
    actor_name VARCHAR(64) NOT NULL,
    text VARCHAR(240) NOT NULL,
    priority INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_announcement_created (created_at),
    KEY idx_announcement_priority (priority, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE robot_activity_log (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    robot_id BIGINT NOT NULL,
    actor_name VARCHAR(64) NOT NULL,
    actor_title VARCHAR(64) NOT NULL,
    kind VARCHAR(32) NOT NULL,
    text VARCHAR(240) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_robot_activity_created (created_at),
    KEY idx_robot_activity_robot (robot_id, created_at),
    KEY idx_robot_activity_kind (kind, created_at),
    CONSTRAINT fk_robot_activity_player FOREIGN KEY (robot_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

     intelligence, spirit, free_points, controller_type, title, personality)
SELECT
    NULL,
    seed.name,
    seed.profession,
    seed.level,
    0,
    50000,
    CASE seed.profession
        WHEN 'mage' THEN 6 + FLOOR(seed.level / 2)
        WHEN 'ranger' THEN 12 + FLOOR(seed.level / 2)
        ELSE 16 + FLOOR(seed.level / 2)
    END,
    CASE seed.profession
        WHEN 'ranger' THEN 17 + FLOOR(seed.level / 2)
        ELSE 10 + FLOOR(seed.level / 2)
    END,
    CASE seed.profession
        WHEN 'warrior' THEN 15 + FLOOR(seed.level / 2)
        ELSE 10 + FLOOR(seed.level / 2)
    END,
    CASE seed.profession
        WHEN 'mage' THEN 18 + FLOOR(seed.level / 2)
        ELSE 8 + FLOOR(seed.level / 2)
    END,
    CASE seed.profession
        WHEN 'mage' THEN 16 + FLOOR(seed.level / 2)
        ELSE 9 + FLOOR(seed.level / 2)
    END,
    0,
    'robot',
    seed.title,
    seed.personality
FROM (
    SELECT 'Aelric Dawnward' AS name, '热血战士' AS title, 'warrior' AS profession, 18 AS level, '喜欢挑战和晒战绩' AS personality
    UNION ALL SELECT 'Mira Starweave', '毒舌法师', 'mage', 21, '关注法杖、暴击和市场价格'
    UNION ALL SELECT 'Leoric Frostguard', '沉稳骑士', 'warrior', 30, '稳定守榜的公会前辈'
    UNION ALL SELECT 'Elyra Moonwhisper', '爱炫耀的游侠', 'ranger', 24, '喜欢晒掉落和低价饰品'
    UNION ALL SELECT 'Tobin Saltmere', '捡漏商人', 'ranger', 16, '总在观察商会价格'
    UNION ALL SELECT 'Borin Ashforge', '强化上头的铁匠', 'warrior', 19, '相信装备要见过火星'
    UNION ALL SELECT 'Veyra Starfall', '幸运旅人', 'mage', 14, '总能捡到意外掉落'
    UNION ALL SELECT 'Cassian Embergrave', '高冷剑士', 'warrior', 34, '榜单前列，只谈结果'
) seed;

     intelligence, spirit, free_points, controller_type, title, personality)
WITH RECURSIVE seq(n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1 FROM seq WHERE n < 192
),
robots AS (
    SELECT
        n,
        1 + MOD(n * 7, 60) AS level,
        CASE MOD(n, 3)
            WHEN 0 THEN 'warrior'
            WHEN 1 THEN 'ranger'
            ELSE 'mage'
        END AS profession
    FROM seq
)
SELECT
    NULL,
    CONCAT(
        CASE MOD(n - 1, 24)
            WHEN 0 THEN 'Aelric'
            WHEN 1 THEN 'Brennor'
            WHEN 2 THEN 'Cedric'
            WHEN 3 THEN 'Dorian'
            WHEN 4 THEN 'Eldric'
            WHEN 5 THEN 'Faelar'
            WHEN 6 THEN 'Garrick'
            WHEN 7 THEN 'Hadrian'
            WHEN 8 THEN 'Isolde'
            WHEN 9 THEN 'Jareth'
            WHEN 10 THEN 'Kaelen'
            WHEN 11 THEN 'Lorian'
            WHEN 12 THEN 'Maelis'
            WHEN 13 THEN 'Nerys'
            WHEN 14 THEN 'Orin'
            WHEN 15 THEN 'Perrin'
            WHEN 16 THEN 'Quillan'
            WHEN 17 THEN 'Rowan'
            WHEN 18 THEN 'Seraphine'
            WHEN 19 THEN 'Thalia'
            WHEN 20 THEN 'Ulric'
            WHEN 21 THEN 'Vaelin'
            WHEN 22 THEN 'Wynna'
            ELSE 'Yseult'
        END,
        ' ',
        CASE FLOOR((n - 1) / 24)
            WHEN 0 THEN 'Stormvale'
            WHEN 1 THEN 'Ashenford'
            WHEN 2 THEN 'Moonbrook'
            WHEN 3 THEN 'Ironhollow'
            WHEN 4 THEN 'Dawnmere'
            WHEN 5 THEN 'Ravenscar'
            WHEN 6 THEN 'Thornwick'
            ELSE 'Starfall'
        END
    ),
    profession,
    level,
    0,
    50000,
    CASE profession
        WHEN 'mage' THEN 6 + FLOOR(level / 2)
        WHEN 'ranger' THEN 12 + FLOOR(level / 2)
        ELSE 16 + FLOOR(level / 2)
    END,
    CASE profession
        WHEN 'ranger' THEN 17 + FLOOR(level / 2)
        ELSE 10 + FLOOR(level / 2)
    END,
    CASE profession
        WHEN 'warrior' THEN 15 + FLOOR(level / 2)
        ELSE 10 + FLOOR(level / 2)
    END,
    CASE profession
        WHEN 'mage' THEN 18 + FLOOR(level / 2)
        ELSE 8 + FLOOR(level / 2)
    END,
    CASE profession
        WHEN 'mage' THEN 16 + FLOOR(level / 2)
        ELSE 9 + FLOOR(level / 2)
    END,
    0,
    'robot',
    CASE MOD(n, 10)
        WHEN 0 THEN '榜单常客'
        WHEN 1 THEN '副本冲层者'
        WHEN 2 THEN '商会倒爷'
        WHEN 3 THEN '强化赌徒'
        WHEN 4 THEN '低价猎人'
        WHEN 5 THEN '巡林老手'
        WHEN 6 THEN '新月旅人'
        WHEN 7 THEN '野队队长'
        WHEN 8 THEN '掉落收藏家'
        ELSE '公会成员'
    END,
    CASE MOD(n, 9)
        WHEN 0 THEN '喜欢在世界频道报掉落'
        WHEN 1 THEN '关注排行榜变化'
        WHEN 2 THEN '经常蹲商会低价装备'
        WHEN 3 THEN '强化成功就会发言'
        WHEN 4 THEN '提醒新人别越级太深'
        WHEN 5 THEN '只聊副本路线'
        WHEN 6 THEN '喜欢比较装备词条'
        WHEN 7 THEN '常年刷日常任务'
        ELSE '偶尔吐槽金币不够用'
    END
FROM robots;

SELECT
    id,
    name,
    'robot',
    CASE MOD(id, 10)
        WHEN 0 THEN CONCAT(title, ' 刚看完战力榜，前排又换人了。')
        WHEN 1 THEN '蛛影林地外缘掉率还行，刷两把就有东西看。'
        WHEN 2 THEN '商会今天的低级蓝装很快被扫走，想买要快。'
        WHEN 3 THEN '强化到 +4 以前还算稳，后面真的要看金币储备。'
        WHEN 4 THEN '越级副本别硬冲，推荐战力差太多会被一套带走。'
        WHEN 5 THEN '有人出护手吗？防御词条高一点的。'
        WHEN 6 THEN '刚整理完背包，一键出售终于清爽多了。'
        WHEN 7 THEN '日常清完记得领任务奖励。'
        WHEN 8 THEN '今天机器人队伍也在刷榜，别被挤下去了。'
        ELSE '世界频道已上线，公会大厅热闹起来了。'
    END
FROM player
WHERE controller_type = 'robot'
ORDER BY id DESC
LIMIT 60;

