ALTER TABLE player
    MODIFY gold BIGINT NOT NULL DEFAULT 100,
    ADD COLUMN real_money BIGINT NOT NULL DEFAULT 0 AFTER gold,
    ADD COLUMN wealth_tier_level INT NOT NULL DEFAULT 0 AFTER real_money,
    ADD COLUMN wealth_tier VARCHAR(64) NOT NULL DEFAULT '贫民' AFTER wealth_tier_level,
    ADD COLUMN last_income_at TIMESTAMP NULL AFTER last_activity_at,
    ADD COLUMN last_recharge_at TIMESTAMP NULL AFTER last_income_at;

ALTER TABLE market_listing
    MODIFY price BIGINT NOT NULL;

ALTER TABLE dungeon_run
    MODIFY gold_gained BIGINT NOT NULL;

ALTER TABLE economy_audit_event
    MODIFY gold_gained BIGINT NOT NULL DEFAULT 0;

CREATE TABLE recharge_order (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    player_name VARCHAR(64) NOT NULL,
    controller_type VARCHAR(16) NOT NULL,
    wealth_tier_level INT NOT NULL,
    wealth_tier VARCHAR(64) NOT NULL,
    rmb_amount BIGINT NOT NULL,
    gold_amount BIGINT NOT NULL,
    reason VARCHAR(96) NOT NULL,
    source_action VARCHAR(96) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_recharge_player (player_id, created_at),
    KEY idx_recharge_controller (controller_type, created_at),
    KEY idx_recharge_tier (wealth_tier_level, created_at),
    CONSTRAINT fk_recharge_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE cash_income_event (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    player_id BIGINT NOT NULL,
    player_name VARCHAR(64) NOT NULL,
    controller_type VARCHAR(16) NOT NULL,
    wealth_tier_level INT NOT NULL,
    wealth_tier VARCHAR(64) NOT NULL,
    rmb_amount BIGINT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_income_player (player_id, created_at),
    KEY idx_income_controller (controller_type, created_at),
    KEY idx_income_tier (wealth_tier_level, created_at),
    CONSTRAINT fk_income_player FOREIGN KEY (player_id) REFERENCES player (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE player
SET wealth_tier_level = 15,
    wealth_tier = '顶级土豪',
    real_money = 0
WHERE controller_type = 'player';

UPDATE player p
JOIN (
    SELECT id, MOD(id * 37, 1421) AS roll
    FROM player
    WHERE controller_type = 'robot'
) seed ON seed.id = p.id
SET p.wealth_tier_level = CASE
        WHEN seed.roll < 320 THEN 0
        WHEN seed.roll < 580 THEN 1
        WHEN seed.roll < 790 THEN 2
        WHEN seed.roll < 960 THEN 3
        WHEN seed.roll < 1090 THEN 4
        WHEN seed.roll < 1185 THEN 5
        WHEN seed.roll < 1255 THEN 6
        WHEN seed.roll < 1307 THEN 7
        WHEN seed.roll < 1345 THEN 8
        WHEN seed.roll < 1372 THEN 9
        WHEN seed.roll < 1391 THEN 10
        WHEN seed.roll < 1404 THEN 11
        WHEN seed.roll < 1412 THEN 12
        WHEN seed.roll < 1417 THEN 13
        WHEN seed.roll < 1420 THEN 14
        ELSE 15
    END,
    p.wealth_tier = CASE
        WHEN seed.roll < 320 THEN '贫民'
        WHEN seed.roll < 580 THEN '节俭平民'
        WHEN seed.roll < 790 THEN '稳定打工人'
        WHEN seed.roll < 960 THEN '小康玩家'
        WHEN seed.roll < 1090 THEN '活跃玩家'
        WHEN seed.roll < 1185 THEN '轻氪玩家'
        WHEN seed.roll < 1255 THEN '月卡党'
        WHEN seed.roll < 1307 THEN '进阶氪金者'
        WHEN seed.roll < 1345 THEN '小资高玩'
        WHEN seed.roll < 1372 THEN '装备收藏家'
        WHEN seed.roll < 1391 THEN '商会大户'
        WHEN seed.roll < 1404 THEN '冲榜玩家'
        WHEN seed.roll < 1412 THEN '土豪'
        WHEN seed.roll < 1417 THEN '大土豪'
        WHEN seed.roll < 1420 THEN '神豪'
        ELSE '顶级土豪'
    END;


UPDATE player
SET real_money = CASE wealth_tier_level
    WHEN 0 THEN 3000 + MOD(id * 97 + 0, 1501)
    WHEN 1 THEN 4500 + MOD(id * 97 + 31, 2001)
    WHEN 2 THEN 6500 + MOD(id * 97 + 62, 3001)
    WHEN 3 THEN 9500 + MOD(id * 97 + 93, 5501)
    WHEN 4 THEN 15000 + MOD(id * 97 + 124, 10001)
    WHEN 5 THEN 25000 + MOD(id * 97 + 155, 20001)
    WHEN 6 THEN 45000 + MOD(id * 97 + 186, 35001)
    WHEN 7 THEN 80000 + MOD(id * 97 + 217, 60001)
    WHEN 8 THEN 140000 + MOD(id * 97 + 248, 100001)
    WHEN 9 THEN 240000 + MOD(id * 97 + 279, 160001)
    WHEN 10 THEN 400000 + MOD(id * 97 + 310, 250001)
    WHEN 11 THEN 650000 + MOD(id * 97 + 341, 350001)
    WHEN 12 THEN 1000000 + MOD(id * 97 + 372, 600001)
    WHEN 13 THEN 1600000 + MOD(id * 97 + 403, 800001)
    WHEN 14 THEN 2400000 + MOD(id * 97 + 434, 1100001)
    ELSE 3500000 + MOD(id * 97 + 465, 1500001)
END;

UPDATE cash_income_event
SET rmb_amount = CASE wealth_tier_level
    WHEN 0 THEN 3000 + MOD(id * 53 + player_id * 17 + 0, 1501)
    WHEN 1 THEN 4500 + MOD(id * 53 + player_id * 17 + 31, 2001)
    WHEN 2 THEN 6500 + MOD(id * 53 + player_id * 17 + 62, 3001)
    WHEN 3 THEN 9500 + MOD(id * 53 + player_id * 17 + 93, 5501)
    WHEN 4 THEN 15000 + MOD(id * 53 + player_id * 17 + 124, 10001)
    WHEN 5 THEN 25000 + MOD(id * 53 + player_id * 17 + 155, 20001)
    WHEN 6 THEN 45000 + MOD(id * 53 + player_id * 17 + 186, 35001)
    WHEN 7 THEN 80000 + MOD(id * 53 + player_id * 17 + 217, 60001)
    WHEN 8 THEN 140000 + MOD(id * 53 + player_id * 17 + 248, 100001)
    WHEN 9 THEN 240000 + MOD(id * 53 + player_id * 17 + 279, 160001)
    WHEN 10 THEN 400000 + MOD(id * 53 + player_id * 17 + 310, 250001)
    WHEN 11 THEN 650000 + MOD(id * 53 + player_id * 17 + 341, 350001)
    WHEN 12 THEN 1000000 + MOD(id * 53 + player_id * 17 + 372, 600001)
    WHEN 13 THEN 1600000 + MOD(id * 53 + player_id * 17 + 403, 800001)
    WHEN 14 THEN 2400000 + MOD(id * 53 + player_id * 17 + 434, 1100001)
    ELSE 3500000 + MOD(id * 53 + player_id * 17 + 465, 1500001)
END;

