INSERT INTO quest_config (id, title, category, description, lore, priority, navigation_target) VALUES
    ('main_001_first_clear', '公会第一枚印章', 'main', '通关蛛影林地·外缘。', '银冠公会需要确认你的战斗记录。去蛛影林地外缘带回第一枚巡林印章。', 10, 'dungeonList'),
    ('main_002_equip', '整理战利品', 'main', '穿戴任意一件装备。', '公会军需官说，真正的冒险者不会把好装备一直塞在背包底。', 20, 'inventory'),
    ('main_003_visit_market', '商会的价签', 'main', '进入冒险者商会。', '黑杉商队已经把新货摆上柜台。去看看市场价格，别让战利品睡在尘土里。', 30, 'market'),
    ('main_004_list_item', '第一张寄售牌', 'main', '在商会上架 1 件装备。', '商会书记给了你一块空白价签。把一件多余装备交给柜台，看看谁会停下脚步。', 40, 'market'),
    ('main_005_view_leaderboard', '银冠战力榜', 'main', '查看排行榜 1 次。', '榜单不是王座，只是一面镜子。看看自己离下一位冒险者还差多少。', 50, 'leaderboard'),
    ('main_006_open_chat', '传讯水晶', 'main', '打开世界聊天 1 次。', '公会大厅的传讯水晶亮了起来。那里有市场传闻、榜单动向和其他冒险者的闲谈。', 60, 'worldChat'),
    ('main_007_enhance', '赤铜工坊的火星', 'main', '强化任意装备 1 次。', '赤铜铁匠博林把锤子搁在铁砧上：一件装备要见过火星，才算真正开始服役。', 70, 'inventory'),
    ('main_008_power_2200', '边境认可', 'main', '战力达到 2200。', '银冠公会把你的名字写进边境候补名单。再提升一点战力，你就能接下更危险的委托。', 80, 'inventory'),
    ('daily_001_clear_twice', '巡林两回', 'daily', '完成任意副本 2 次。', '今日巡林记录需要两枚新鲜印章，公会书记会在晚钟前核对。', 110, 'dungeonList'),
    ('daily_002_kill_20', '清剿蛛影', 'daily', '击败 20 只怪物。', '蛛网又爬上了旧路标。清出一段路，商队就能安全些。', 120, 'dungeonList'),
    ('daily_003_enhance', '工坊炉火', 'daily', '强化任意装备 1 次。', '赤铜工坊今天的炉火很稳，博林说适合敲上一锤。', 130, 'inventory'),
    ('daily_004_leaderboard', '榜单晨检', 'daily', '查看排行榜 1 次。', '银冠战力榜每天都会动。看一眼目标，别让前面的背影跑远。', 140, 'leaderboard'),
    ('daily_005_chat', '水晶回声', 'daily', '打开世界聊天 1 次。', '传讯水晶里总有新的价签、传闻和榜单碎语。今天也去听一听。', 150, 'worldChat'),
    ('ach_001_rare_item', '蓝光初现', 'achievement', '首次获得稀有及以上装备。', '当第一缕蓝色魔光穿过蛛网，公会大厅里总会有人抬头。', 210, 'dungeonList'),
    ('ach_002_clear_10', '十枚巡林印章', 'achievement', '累计通关任意副本 10 次。', '十次归来，靴底会记住林地的泥，也会记住你没有退缩。', 220, 'dungeonList'),
    ('ach_003_enhance_success_3', '三次成锤', 'achievement', '累计强化成功 3 次。', '博林在账本旁画了三颗火星，这是他少见的称赞。', 230, 'inventory'),
    ('ach_004_market_purchase', '第一笔买入', 'achievement', '首次从市场购买装备。', '商会柜台敲下了第一枚属于你的买入印章。', 240, 'market'),
    ('ach_005_market_sale', '第一张成交单', 'achievement', '首次在市场售出装备。', '有人买走了你的战利品。商会书记把这张成交单夹进了你的档案。', 250, 'market'),
    ('ach_006_rank_top_100', '榜上有名', 'achievement', '首次进入排行榜前 100。', '银冠战力榜给你留出了一个位置，哪怕只是末席，也足够让新人记住你的名字。', 260, 'leaderboard')
